-- ============================================================================
-- 10_todos.sql — the actionable revision list generated from an analysis.
-- ============================================================================
-- Findings tell a student what is wrong. Todos tell them what to do about it,
-- in an order, with somewhere to track progress. Generated by the TODO_LIST job
-- but freely editable afterwards — this is one of the few analysis-derived
-- tables the user may write to.
-- ============================================================================

create table public.todo_groups (
  id                  uuid primary key default gen_random_uuid(),
  paper_analysis_id   uuid not null references public.paper_analyses (id) on delete cascade,
  paper_id            uuid not null references public.papers (id) on delete cascade,
  user_id             uuid not null references auth.users (id) on delete cascade,

  title               text not null,
  description         text not null default '',
  sort_order          integer not null default 0,

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  constraint todo_groups_title_not_empty check (length(btrim(title)) > 0)
);

create index todo_groups_analysis_idx on public.todo_groups (paper_analysis_id);
create index todo_groups_paper_id_idx on public.todo_groups (paper_id);
create index todo_groups_user_id_idx on public.todo_groups (user_id);

create trigger todo_groups_set_user_id
  before insert on public.todo_groups
  for each row execute function public.set_user_id_from_paper_analysis();

create trigger todo_groups_set_updated_at
  before update on public.todo_groups
  for each row execute function public.set_updated_at();

comment on table public.todo_groups is 'Thematic grouping of revision tasks, e.g. "Citations", "Structure".';

-- ----------------------------------------------------------------------------
-- todo_items — one actionable task.
--
-- finding_id is ON DELETE SET NULL rather than CASCADE: if the underlying
-- finding is removed, the student's task and their progress on it survive. The
-- task is theirs, not the analysis's.
--
-- due_at drives the TODO_DUE_SOON notification in P15.
-- ----------------------------------------------------------------------------
create table public.todo_items (
  id                  uuid primary key default gen_random_uuid(),
  todo_group_id       uuid not null references public.todo_groups (id) on delete cascade,
  user_id             uuid not null references auth.users (id) on delete cascade,

  finding_id          uuid references public.findings (id) on delete set null,
  check_result_id     uuid references public.check_results (id) on delete set null,

  title               text not null,
  description         text not null default '',
  page_number         integer check (page_number > 0),

  is_done             boolean not null default false,
  completed_at        timestamptz,
  due_at              timestamptz,
  sort_order          integer not null default 0,

  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),

  constraint todo_items_title_not_empty check (length(btrim(title)) > 0)
);

create index todo_items_group_idx on public.todo_items (todo_group_id);
create index todo_items_user_id_idx on public.todo_items (user_id);
create index todo_items_finding_id_idx on public.todo_items (finding_id);
create index todo_items_open_idx
  on public.todo_items (todo_group_id)
  where not is_done;
-- Drives the TODO_DUE_SOON notification sweep.
create index todo_items_due_idx
  on public.todo_items (due_at)
  where due_at is not null and not is_done;

create trigger todo_items_set_user_id
  before insert on public.todo_items
  for each row execute function public.set_user_id_from_todo_group();

create trigger todo_items_set_updated_at
  before update on public.todo_items
  for each row execute function public.set_updated_at();

comment on table public.todo_items is
  'One revision task. finding_id is SET NULL on delete — the task is the student''s, not the analysis''s.';
